    44|function extractTextFromPayload(payload: unknown): string {
    45|  if (!payload || typeof payload !== 'object') return '';
    46|  const record = payload as Record<string, unknown>;
    47|  const text = readTrimmed(record.text) || readTrimmed(record.transcript);
    48|  if (text) return text;
    49|  const words = Array.isArray(record.words) ? record.words : [];
    50|  return words
    51|    .map((word) => typeof word === 'object' && word ? readTrimmed((word as Record<string, unknown>).text) : '')
