     1|/**
     2| * Shared provider auto-detection utility.
     3| *
     4| * The key prefix determines the correct AI provider endpoint:
     5| *   vck_  → Vercel AI Gateway (https://ai-gateway.vercel.sh/v1)
     6| *   sk-   → OpenAI direct API (https://api.openai.com/v1)
     7| *
     8| * This module is imported by all secondary AI service files (multimodal,
     9| * transcription, embeddings, image generation, global intelligence) so they
    10| * all route to the correct endpoint based on whichever key is loaded on the
    11| * host — without each file duplicating the detection logic.
    12| */
    13|
    14|export const VERCEL_AI_GATEWAY_BASE = 'https://ai-gateway.vercel.sh/v1';
    15|export const OPENAI_DIRECT_BASE = 'https://api.openai.com/v1';
    16|
    17|function readTrimmed(value: unknown): string {
    18|  return typeof value === 'string' ? value.trim() : '';
    19|}
    20|
    21|import { isBlockedDomain } from './ivx-domain-blocklist';
    22|
    23|/** Returns the API key from OPENAI_API_KEY or IVX_AI_GATEWAY_KEY (fallback). */
    24|export function getIVXApiKey(): string {
    25|  return readTrimmed(process.env.OPENAI_API_KEY) || readTrimmed(process.env.IVX_AI_GATEWAY_KEY);
    26|}
    27|
    28|/** Detect the provider type from the key prefix. */
    29|export function detectIVXProviderType(): 'vercel_gateway' | 'openai_direct' | 'unknown' {
    30|  const key = getIVXApiKey();
    31|  if (!key) return 'unknown';
    32|  if (key.startsWith('vck_')) return 'vercel_gateway';
    33|  if (key.startsWith('sk-')) return 'openai_direct';
    34|  return 'unknown';
    35|}
    36|
    37|/**
    38| * Returns the correct base URL for the loaded API key.
    39| * If IVX_AI_GATEWAY_URL (or IVX_AI_BASE_URL) is explicitly set and not a blocked
    40| * external domain, it takes priority. Otherwise, the key prefix determines the endpoint.
    41| */
    42|export function autoDetectGatewayBaseUrl(): string {
    43|  const configured = readTrimmed(process.env.IVX_AI_GATEWAY_URL) || readTrimmed(process.env.IVX_AI_BASE_URL);
    44|  if (configured && !isBlockedDomain(configured)) {
    45|    return configured.replace(/\/+$/, '');
    46|  }
    47|  const key = getIVXApiKey();
    48|  if (key && key.startsWith('vck_')) {
    49|    return VERCEL_AI_GATEWAY_BASE;
    50|  }
    51|  return OPENAI_DIRECT_BASE;
    52|}
    53|
    54|/**
    55| * Normalize a model name for the active provider.
    56| * Vercel AI Gateway requires the `openai/` prefix (e.g. `openai/gpt-4o`).
    57| * OpenAI direct API uses bare model names (e.g. `gpt-4o`).
    58| */
    59|export function normalizeModelForGateway(model: string): string {
    60|  const bare = model.replace(/^openai\//, '');
    61|  const providerType = detectIVXProviderType();
    62|  if (providerType === 'vercel_gateway') {
    63|    return `openai/${bare}`;
    64|  }
    65|  return bare;
    66|}

