      ok: false,
      error: errorMsg,
      marker: IVX_VOICE_CHAT_API_MARKER,
      durationMs: Date.now() - start,
    }, { status: 500 });
  }
}

/** Handle transcribe-only endpoint. */
export async function handleVoiceChatTranscribe(request: Request): Promise<Response> {
  const start = Date.now();

  try {
