    return {
      ok: true,
      audioBase64,
      audioBytes,
      format: 'mp3',
      voice,
      model,
      provider: 'rork_gateway',
      durationMs: Date.now() - start,
      error: null,
    };
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : String(err);
    console.error('[IVX TTS] Toolkit synthesis error:', errorMsg);
    return {
      ok: false,
      audioBase64: null,
      audioBytes: null,
      format: 'mp3',
      voice,
      model,
      provider: 'rork_gateway',
      durationMs: Date.now() - start,
      error: errorMsg,
    };
  }
}

